/// Control metrics of one density, in logical pixels.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Density {
    pub control_height: f32,
    pub control_padding_x: f32,
    pub row_height: f32,
    pub gap: f32,
    pub panel_padding: f32,
}

impl Density {
    pub const COMPACT: Density = Density {
        control_height: 24.0,
        control_padding_x: 8.0,
        row_height: 24.0,
        gap: 4.0,
        panel_padding: 8.0,
    };
    pub const REGULAR: Density = Density {
        control_height: 32.0,
        control_padding_x: 12.0,
        row_height: 32.0,
        gap: 8.0,
        panel_padding: 12.0,
    };
    pub const COMFORTABLE: Density = Density {
        control_height: 40.0,
        control_padding_x: 16.0,
        row_height: 40.0,
        gap: 12.0,
        panel_padding: 16.0,
    };
}

